/*deleteMasterClMgCreditDeptPop*/
		DELETE ICOMCOD3
		WHERE BUYER = 'KRKORE0001'
		AND TYPE = 'BYMP'
		AND CODE1 = #{COM_CODE}
		AND CODE2 = #{CODE2}


/*deleteMasterClMgBondExcpPop*/
		DELETE ICOMCOD3
		WHERE BUYER = 'KRKORE0001'
		AND TYPE = 'EXMP'
		AND CODE1 = REPLACE(#{IRS_NO},'-','')
		AND CODE2 = #{KEP_DEPT}
